-- ---------- الأسئلة والإرشادات ----------
insert into public.faq (id, cat, q, a, sort_order)
select x.id, x.cat, x.q, x.a, x.sort_order
from jsonb_to_recordset('[
  {"id":"f1","cat":"الصيدليات والدواء","q":"كيف أعرف صيدلية المناوبة اليوم في حلفايا؟","a":"افتح صفحة «الصيدليات المناوبة» في الدليل، أو انظر شريط المناوبة في الصفحة الرئيسية حيث تُحدَّث البطاقة تلقائياً حسب اليوم. يمكنك أيضاً الاتصال مباشرة برقم الصيدلية المذكور للتأكد قبل الذهاب.","sort_order":1},
  {"id":"f2","cat":"الأطفال","q":"ارتفعت حرارة طفلي — متى أقلق وأراجع الطبيب؟","a":"معظم الحالات تتحسن بالخافض الحراري والسوائل. راجع الطبيب فوراً إذا كان عمر الطفل أقل من 3 أشهر، أو استمرت الحرارة فوق 39° أكثر من 48 ساعة، أو ظهرت علامات خطر: خمول شديد، رفض الرضاعة، تنفس سريع، أو تشنجات.","sort_order":2},
  {"id":"f3","cat":"الصيدليات والدواء","q":"هل أستطيع شراء المضاد الحيوي دون وصفة؟","a":"لا ينصح بذلك أبداً. المضادات الحيوية لا تفيد في العدوى الفيروسية، والاستخدام الخاطئ يسبب مقاومة بكتيرية تجعل العلاج أصعب لاحقاً. اطلب فحصاً من طبيب عام أو أخصائي ليحدد الدواء ومدته المناسبتين.","sort_order":3},
  {"id":"f4","cat":"الأمراض المزمنة","q":"لدي ضغط دم مرتفع — ما الفحوصات الدورية التي أحتاجها؟","a":"اقيس ضغطك منزلياً وأسجّل القراءات، وأجرِ دورياً: صورة دم كاملة، سكر صائم ودهنيات، وظائف كلى (يوريا وكرياتينين)، ومخطط قلب سنوياً. راجع طبيب القلب أو الباطنية كل 3-6 أشهر حسب حالتك.","sort_order":4},
  {"id":"f5","cat":"الأطفال","q":"أين أتابع تطعيمات طفلي في حلفايا؟","a":"التطعيمات الأساسية تُقدَّم مجاناً في المركز الصحي الحكومي بحلفايا، ويُنصح بإحضار دفتر التطعيم في كل زيارة. تعرف على مواعيد يوم التطعيم من بيانات المركز في صفحة «المراكز الصحية».","sort_order":5},
  {"id":"f6","cat":"صحة المرأة","q":"متى أبدأ بالفحص المبكر لسرطان الثدي؟","a":"يُنصح بالفحص الذاتي الشهري بعد سن العشرين، وبصورة الثدي السريرية كل 1-3 سنوات بين سن 20 و40، ثم صورة ماموغرام دورية بعد سن الأربعين أو أبكر عند وجود تاريخ عائلي. استشيري طبيبتك النسائية لتحديد جدول مناسب.","sort_order":6},
  {"id":"f7","cat":"الأمراض المزمنة","q":"عندي سكري — ما الفحوصات التي أكررها دورياً؟","a":"الأساسيات: سكر صائم وتراكمي (HbA1c) كل 3-6 أشهر، فحص قعر العين سنوياً، فحص الكلى (ألبومين بولي) سنوياً، وفحص القدمين في كل زيارة. المخابر المحلية في الدليل توفر هذه الحزم بأسعار مخفضة غالباً.","sort_order":7},
  {"id":"f8","cat":"الإسعافات الأولية","q":"ماذا أفعل عند حرق بسيط في البيت؟","a":"ضع المنطقة تحت ماء فاتر جارٍ لمدة 10-20 دقيقة، ثم غطِّها بضماد نظيف غير مشدود. لا تستخدم معجون الأسنان أو الزبدة ولا تفقّأ الحباب. راجع المشفى إذا كان الحرق واسعاً أو في الوجه أو اليدين أو عند الأطفال الصغار.","sort_order":8},
  {"id":"f9","cat":"الصيدليات والدواء","q":"كيف أخزّن الأدوية في البيت بشكل صحيح؟","a":"احفظ الأدوية بعيداً عن الحرارة والرطوبة وضوء الشمس المباشر — وخاصة خارج ثلاجة الصيدلية (حمامات ومطابخ أماكن غير مناسبة غالباً). تحقق من تاريخ الصلاحية دورياً وتخلص من العبوات المنتهية، واحفظها بعيداً عن متناول الأطفال.","sort_order":9},
  {"id":"f10","cat":"الفحوصات","q":"ما الفحوصات الوقائية المفيدة سنوياً لشخص سليم؟","a":"فحص عام مفيد بعد سن الأربعين: صورة دم كاملة، سكر صائم، دهنيات (كوليسترول)، وظائف كبد وكلى، وتحليل بول. أضف قياس ضغط ووزن ومؤشر كتلة جسم، ومواعيد متابعة سنوية مع طبيب العائلة.","sort_order":10}
]'::jsonb) as x(id text, cat text, q text, a text, sort_order int)
on conflict (id) do update set cat = excluded.cat, q = excluded.q, a = excluded.a, sort_order = excluded.sort_order;